        return std::format_to(ctx.out(), "学生{}:{}", s.id, s.name);   // 任务：只改这一处
    }
};

int main() {
    Student s{1001, "小明"};
    std::println("{}", s);
    std::println("名单：{}", s);
    return 0;
}

